 t('Efforts','<b>Positive Indigenisation Lists</b> (411 items services; 10 lists, 5,521 items DPSUs)','<b>75%</b> of capital acquisition budget for Indian firms; <b>IDDM</b> priority (DAP 2020)','Simplified licensing; <b>SRIJAN</b> portal; <b>Defence Industrial Corridors</b> (UP, TN); <b>Mission DefSpace</b>','Lines of credit, Exim, offset; <b>MEA and embassies</b> promote',w=26),
