dict(id=36,title='Integrated Theatre Command and CDS',part=2,icon='shield',pyq='Higher defence reforms',
 simple='India has 17 single-service commands. The CDS (2020) and DMA push towards theatre commands, but critics say build jointness and doctrine first.',
 pages='Handout (Misc) p.31-38',prio='H',
 nodes=[
 fl(['1949 Joint Services Wing / NDA (1955)','Kargil 1999: poor coordination','2000 GoM / 2001 report: CDS','2011-12 Naresh Chandra: permanent chairman COSC','2016 Shekatkar: 3 theatre commands','2020 first CDS + DMA','2023 Inter-Services Organisations Act'],'Road to jointness',4),
 t('Early tri-service institutions','Joint Services Wing (Dehradun 1949); <b>NDA</b> (inaugurated 1955); DSSC Wellington; NDC Delhi — but operational jointness limited',w=26),
 t('Commands today','<b>Unified:</b> Andaman &amp; Nicobar Command (2001, theatre) · <b>Strategic Forces Command</b> (2003, functional)','<b>17 single-service commands:</b> Army 7 · Air Force 7 · Navy 3','<b>Air Defence Command</b> (2020 idea) — <b>not operationalised</b> (June 2023): IAF says air defence and offence are interdependent','Specialised: <b>Defence Cyber Agency</b> (could become Information Warfare Command), <b>AFSOD</b>, Defence Space Agency; proposed Logistics, Training and Doctrinal commands',w=26),
 bx('ca','<b>Inter-Services Organisations (Command, Control and Discipline) Act 2023:</b> enabling law; Centre can constitute inter-service organisations; <b>Commander-in-Chief / Officer-in-Command</b> has disciplinary powers over all personnel irrespective of service; existing Service Acts unchanged; Centre can issue directions.'),
 sec('CHIEF OF DEFENCE STAFF','r'),
 t('Evolution','Post-1947: <b>Chiefs of Staff Committee</b> (triumvirate, Chairman-COSC = title only)','<b>Kargil 1999 → GoM 2000 → 2001 report</b>: CDS (deferred); <b>Naresh Chandra 2011-12</b>: CDS as <b>permanent chairman COSC</b> compromise; both urged integrating HQs with MoD, cross-staffing',w=26),
 t('About CDS','<b>Four-star</b>, pay equal to service chiefs; <b>no command</b> over chiefs; <b>primus inter pares</b>; precedence <b>12th</b>','<b>Permanent Chairman COSC</b> · <b>Principal Military Adviser</b> to Defence Minister · <b>Secretary, Department of Military Affairs (DMA)</b>','Command over <b>DCyA, DSA, AFSOD</b> via Integrated Defence Staff; promotes jointness in procurement, training, staffing','Equivalents: Pakistan CJCSC · UK CDS · US CJCS',w=26),
 t('Issues','No operational command; limited political involvement in planning; DMA reduced civilian oversight (promotions, postings); Defence Secretary role diluted',w=26),
 t('Way forward','Define CDS operational role vs chiefs\' administrative duties; <b>Vice CDS</b>; empower command over theatres; professional independence; continuous evaluation',w=26),
 sec('ISSUES WITH THEATRE COMMANDS','b'),
 t('Issues','<b>Lack of true jointness</b> (training, operations, planning); successes by good fortune','<b>Premature push</b>; separate land/maritime/air-defence proposal makes one service dominant','Service-specific war plans; <b>air power</b> contested (IAF proprietary view); <b>rotational leadership</b> debate','Need <b>National Security Doctrine</b> before theatrisation',w=26),
 t('Way forward','<b>Jointness first</b>; <b>pilot one theatre</b> (northern: Kargil, Ladakh)','Develop <b>"purple" personnel</b> with multi-service experience','<b>Joint war-fighting doctrine</b>; learn from global examples',w=26),
 bx('pk','<b>Shekatkar Committee (Dec 2016)</b> under Manohar Parrikar\'s MoD recommended three integrated theatre commands.'),
 ],
 recall=[('First CDS year?','2020'),('Which committee proposed 3 theatre commands?','Shekatkar 2016'),('Air Defence Command status?','Not operationalised (June 2023)'),('CDS ranks?','12th in precedence; four-star; primus inter pares')],
 terms=[['Theatre command','Single commander controls army, navy, air assets for one geographic region.'],['Purple officer','Officer with experience across all three services.']],
 simple_b=['**CDS and DMA (2020)** started jointness; **theatre commands** still pending.','Critics: build **jointness and doctrine first**, pilot one theatre.']),
dict(id=34,title='UAPA and NIA',part=2,icon='gavel',pyq='Anti-terror law debates',
 simple='UAPA designates organisations and (since 2019) individuals as terrorists; NIA is the central counter-terror agency (2008). Both face federalism and due-process criticism.',
 pages='Handout (Misc) p.39-46',prio='H',
 nodes=[
 bx('ca','<b>July 2026:</b> MHA designated <b>23 more individuals</b> as terrorists under <b>S.35 UAPA</b> (Fourth Schedule): 17 Pakistani, 6 Indian, all operating from Pakistan or PoJK; earlier 57 → total <b>80</b>. <b>NIA (29 Jul 2026):</b> 690 cases, 169 judgments, 156 convictions = <b>92.31%</b>.'),
 sec('UAPA AMENDMENT 2019','r'),
 tb(['Provision','What it does'],['<b>S.35</b> designation','Centre can designate <b>organisations</b>; <b>2019</b> extends to <b>individuals</b> (Fourth Schedule)'],['Property seizure','Needs DGP approval; if NIA investigates, <b>DG NIA</b> approval'],['Investigation','DSP/ACP or above; <b>NIA Inspectors</b> and above can investigate'],['Schedule of treaties','Adds <b>International Convention for Suppression of Acts of Nuclear Terrorism (2005)</b> to nine treaties']),
 t('Criticism','<b>Arbitrary labelling</b>: no FIR, chargesheet or conviction needed; fails "just, fair, reasonable"','<b>Fundamental rights</b>: Art. 19 speech, assembly, association; dissent criminalised','<b>No safeguards</b>: no judicial review/appeal for designation; burden shifts; <b>Watali (2019)</b> limits bail scrutiny; <b>Thwaha Fasal (2021)</b> slightly easier bail','<b>Federal encroachment</b>; <b>low conviction</b> — 2.2% of UAPA cases 2016-19; erodes judicial role',w=26),
 t('Way forward','Use as <b>last resort</b>; narrow definitions of "unlawful activity/terrorist act" (protect protest, per <b>Art. 19(1)(a)</b>, <b>Maqbool Fida Hussain v. Rajkumar Pandey 2008</b>)','<b>Independent review</b> mechanism; amend <b>S.43D(5)</b> (presumption of innocence); clear bail-denial grounds',w=26),
 sec('NIA ACT 2008','b'),
 t('About NIA','<b>Central counter-terror agency</b>, HQ New Delhi; formed after <b>26/11</b>; Bill by P. Chidambaram Dec 2008; came into existence <b>31 Dec 2008</b>, functioning 2009','Investigates offences against sovereignty/security: friendly relations with states, atomic facilities, <b>arms-drug-FICN smuggling</b>, infiltration, treaty offences — across States on MHA order','<b>2019 Amendment</b>: adds <b>human trafficking, counterfeit currency, prohibited arms, cyber-terrorism, Explosive Substances Act</b>; investigate offences <b>outside India</b>; Special Court in <b>New Delhi</b>',w=26),
 t('Analysis','<b>Constitutional validity</b>: police/public order = State subjects; Soli Sorabjee Committee and Law Ministry: Arts. <b>249 / 252</b> or amendment; <b>Entry 93, List I</b> gives some basis','<b>Functioning</b>: investigation but not prevention (no intelligence role); <b>superintendence</b> undefined (politicisation); executive decides scheduled offence; <b>S.6(3)</b> gives Centre 15 days to decide',w=26),
 t('Way forward','<b>International cooperation</b> (information sharing, extradition, joint ops) · <b>coordination with State agencies</b> (joint task forces, shared databases) · <b>judicial oversight</b>',w=26),
 ],
 recall=[('S.35 UAPA?','Designation of terrorist organisations; individuals after 2019'),('Total individuals designated by July 2026?','80'),('NIA conviction rate (Jul 2026)?','92.31%'),('Conviction of UAPA cases 2016-19?','2.2%')],
 terms=[['Fourth Schedule (UAPA)','List of individuals designated as terrorists.'],['Superintendence','Control over an agency; the NIA Act does not define it.']],
 simple_b=['**UAPA** now allows designating **individuals**; **NIA** can probe across States and abroad.','Concerns: **due process, federalism, low UAPA conviction rate**.']),
